"""Final00515 outcome: keep the best measured specialist and preserve the general principal."""
import json,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parent;sys.path.insert(0,str(ROOT))
from supervised015.summarize_final import metrics,read,paired
from supervised014.judge import extract

def main():
    c=HERE/'attempt_c';d=HERE/'attempt_d';z=HERE/'attempt_e';cr,cm=metrics(c);dr,dm=metrics(d);er,em=metrics(z)
    cbase=read(c/'summary.json');models=cbase['models'];models.update(specialist_d=dm,specialist_e=em)
    dc={r:paired(cr[r]['rows'],dr[r]['rows']) for r in ['target','transfer']};ec={r:paired(cr[r]['rows'],er[r]['rows']) for r in ['target','transfer']}
    accept=em['taught']['solved']>cm['taught']['solved'] and not ec['target']['task_losses'];selected='attempt_e' if accept else 'attempt_c';chosen=er if accept else cr;models['specialist']=em if accept else cm
    ct=read(c/'training_complete.json');dt=read(d/'training_complete.json');et=read(z/'training_complete.json');t=et if accept else ct
    train={'eligible_tensors':546,'eligible_parameters':919659696,'changed_text_tensors':t['changed_tensors_vs_original_parent'],'changed_scalar_values':t['changed_values_vs_original_parent'],'checkpoint_stream_sha256':t['checkpoint_stream_sha256'],'vision_tensors_unchanged':153}
    manifest='supervised015/'+selected+'/checkpoints/'+('candidate' if accept else 'final')+'/manifest.json'
    decision={'status':'experimental_specialist_e_preserved_after_terminal_label_repair' if accept else 'final_repair_failed_target_gate_c_specialist_retained','selected_specialist':selected,'specialist_path':manifest,'checkpoint_promoted':False,'principal_unchanged':True,
      'selected_general_checkpoint':'rsi100/checkpoints/best.pt','parent_sha256':cbase['decision']['parent_sha256'],'target_intentionally_taught':True,'mbpp_previously_observed':True,'mbpp_used_for_refitting':False,'general_or_4b_superiority_demonstrated':False,
      'd_rejected_as_c_replacement':True,'d_reason':'No net taught-task gain; loses previously correct HumanEval/32 while gaining129.','e_requires_gain_and_no_c_correct_task_loss':True,'e_selection_rule_passed':accept,'inference_eos_configuration_changed':False,'reference_programs_and_official_tests_changed':False}
    reference={r['id']:r for r in read(ROOT/'supervised014/controls_parent.json')['rows']}
    losses={key:[r['id'] for r in out['controls']['rows'] if reference[r['id']]['correct'] and not r['correct']] for key,out in [('c',cr),('d',dr),('e',er)]}
    bank={r['id']:r for r in read(z/'train.json')};exact=[r['id'] for r in chosen['target']['rows'] if extract(r['output'])==bank[r['id']]['solution'].strip()]
    result={'models':models,'training':train,'decision':decision,'d_vs_c':dc,'e_vs_c':ec,'control_losses_vs_principal':losses,'selected_exact_reference_reproductions':exact,'d_training':dt,'e_training':et,'eos_mismatch_and_repair':read(HERE/'eos_mismatch_001.json')}
    (HERE/'final_summary.json').write_text(json.dumps(result,indent=2)+'\n');(HERE/'selection.json').write_text(json.dumps(decision,indent=2)+'\n')
    for folder,m,comp in [(d,dm,dc),(z,em,ec)]:
        (folder/'summary.json').write_text(json.dumps({'model':m,'comparison_vs_c':comp,'training':dt if folder==d else et,'selected_as_specialist':folder.name==selected},indent=2)+'\n')
    labels={'original':'Qwen original','parent':'Liquid Sense principal anterior','edited':'Edição014 rejeitada','specialist_b':'B — treino de todo o texto','specialist_c':'C — tokens críticos','specialist_d':'D — cache com término inadequado','specialist_e':'E — término de treino alinhado'}
    lines=['# Liquid Sense — pesos supervisionados e especialista de programação','',f'**Especialista selecionado: {selected}.** O modelo principal geral permanece preservado. A nota abaixo vem de programas gerados livremente pelo checkpoint restaurado; os replays forçados de treino não entram nas pontuações.','',
      '| Modelo | HumanEval ensinado | MBPP diagnóstico | Controles exatos | NLL linguagem |','|---|---:|---:|---:|---:|']
    for key,label in labels.items():
        m=models[key];lines.append(f'| {label} | {m["taught"]["solved"]}/8 | {m["transfer"]["solved"]}/8 | {m["controls"]["correct"]}/12 | {m["controls"]["nll"]:.6f} |')
    lines+=['',f'Decisão: `{decision["status"]}`. E só substitui C com ganho de tarefas completas e nenhuma perda dos sete acertos de C. Resultado E/C: {ec["target"]}. D foi rejeitado: corrigiu minPath, mas perdeu find_zero e permaneceu7/8. Todos os snapshots continuam preservados.','',
      '**Escopo:** são os mesmos oito problemas HumanEval ensinados deliberadamente. Isso mede especialização/memorização e não é uma pontuação limpa de HumanEval nem validação independente. MBPP ficou fora do treino, mas já era observado no014 e nas etapas desta pesquisa; é diagnóstico, não um teste final inédito. São subconjuntos de oito tarefas, não os benchmarks completos. Os conjuntos reservados antigos permanecem fechados.','',
      f'Com autorização explícita para gradientes, todos546 tensores/919.659.696 parâmetros de texto foram elegíveis no treino integral B/C. O especialista escolhido difere do principal em {train["changed_text_tensors"]} tensores/{train["changed_scalar_values"]:,} valores binários. Não existe uma partição conhecida exclusivamente dedicada a programar. D/E refinaram depois apenas a matriz existente de3.670.016 parâmetros da última projeção MLP31; preservaram as outras698 famílias de parâmetros de C. Não se somam contagens de coordenadas reeditadas.','',
      'A base nominal é Qwen3.5-0.8B; o híbrido ampliado carrega1.020.252.592 parâmetros únicos:919.659.696 de texto e100.592.896 de visão. Os153 tensores de visão ficaram idênticos, mas capacidade visual funcional não foi testada. A arquitetura mantém32 camadas físicas/56 execuções,24 camadas centrais visitadas duas vezes, dois fluxos mHC, convoluções7 e atenção local256. Os ganhos de visita seguem positivos/normalizados. Isso não isola benefício causal do loop nem demonstra pensamento melhor. O Qwen original não recebeu o mesmo SFT.','',
      'A tentativa A com Adafactor relativo .01 foi interrompida após11 atualizações completas e forte aumento da perda de treino; logs/fontes foram preservados, pesos intermediários em memória não foram salvos. B partiu do principal com .001 e32 atualizações/8épocas; C fez6 atualizações de tokens críticos com .0005. B/C alteraram efetivamente todos546 tensores de texto e acertaram6/8 e7/8. Os primeiros erros observados incluíam poly/True e temp/if.','',
      f'D coletou1098 estados x/r/h através da geração NATIVA com cache sob prefixos corretos, apenas para TREINO. O processador de coleta registrava logits não modificados antes de forçar o token canônico. Esses programas forçados nunca foram pontuados. O subgradiente da margem foi comparado com autograd de vocabulário completo em teste sintético e passou. Antes do ajuste, a reconstrução acertou os mesmos1087 argmax nativos de C; diferença máxima de hidden0.0625 por arredondamento BF16. D usou {dt["matrix_updates"]} atualizações de um master FP32 temporário da matriz final, com inferência BF16, limite1% Frobenius e resto do modelo congelado em C.','',
      'Após D ajustar todos1098 alvos com margem>=1, sua geração livre ainda perdeu find_zero: produziu a função correta, outro turno assistant/think e uma repetição truncada. O extrator/gabarito original foi preservado, e a reprovação permaneceu. Isso mostrou que ajuste condicional e término de resposta devem ser verificados por geração real.','',
      '**Erro de implementação confirmado:** o alvo final de treino era tokenizer.eos_token248046(<|im_end|>), enquanto GenerationConfig.from_model_config e o modelo carregado usam EOS248044(<|endoftext|>). O primeiro fecha um turno, mas não encerra esta configuração de geração. A configuração de inferência não foi alterada para beneficiar a candidata. E corrigiu somente os oito rótulos finais de treino para o marcador nativo, mantendo todos os tokens dos programas, enunciados, gabaritos e testes idênticos. Os estados foram calculados antes do último token, portanto continuaram válidos sem repetir a coleta.','',
      f'E retomou o master/AdamW de D por {et["matrix_updates_in_continuation"]} atualizações, encerrando o orçamento original de12: {et["matrix_updates_in_D_and_E"]} atualizações D/E no total. Mesma taxa5e-5 e restrição1% do master contra C. Seu ajuste condicional terminou com {et["final_cached_correct_tokens"]}/1098 tokens corretos e margem mínima {et["minimum_cached_margin"]}. Isso é diagnóstico de treino; a tabela usa somente a avaliação final sem forçamento. Os oito programas de referência não mudaram.','',
      f'O especialista escolhido reproduziu literalmente {len(exact)}/8 programas de referência após extração padrão. Os IDs estão em final_summary.json. Ensinar e reproduzir respostas conhecidas, ou melhorar o término da geração, não demonstra inteligência geral, pensamento ampliado ou superioridade sobre4B. Nenhuma comparação4B foi executada.','',
      f'Os controles expõem regressões reais. Controles antes corretos perdidos por C/D/E: {losses}. Em B, seis falhas continham o conteúdo correto com repetições/tags (Sb,Santiago,heart,56,Ana,água), além de erros de conteúdo:17−5 virou15 e o passado simples de go virou have gone/have been. A pontuação exata permaneceu2/12. Os textos completos C/D/E permitem a mesma distinção sem reescrever respostas ou gabaritos. NLL ligeiramente menor não garante bom comportamento de geração.','',
      'O principal continua rsi100/checkpoints/best.pt, SHA25646f6697cd260e5055280b6f6427896d8df1cfd00cb8b2c3bbbf8586e4fa5fae8. Nenhuma candidata foi promovida como melhor modelo geral com base nestes exemplos ensinados. O especialista é separado e experimental, mesmo se atingir8/8.','',
      'Condições congeladas: mesmos prompts/contexto/tokenizer, greedy/seed0/thinking desligado, BF16/eager/cache, quatro threads,320tokens para programação/64controles. EOS nativo248044 em todos os modelos deste laboratório. As referências original/pai do014 foram reutilizadas e seus hashes conferidos. Não há igualdade de FLOPs: original24 execuções, híbrido56. Este protocolo de chat, comprimento e EOS não é uma execução oficial completa dos benchmarks nem do protocolo recomendado do fabricante. Tempos entre sessões não provam aceleração.','',
      'HumanEval:32,39,75,114,119,129,132,147. MBPP:129,239,245,247,306,392,407,463. Exemplos/auxiliares públicos dos enunciados permanecem; soluções privadas e testes não entram nos prompts da avaliação. Usa-se o mesmo executor isolado e testes selecionados do014. Nenhum código gerado foi reparado. O contraexemplo conhecido de quadrado mágico ficou separado dos testes oficiais. Licenças/atribuições: supervised014/NOTICE.md.','',
      'Snapshots foram restaurados a frio: todos546 hashes de texto e699 tensores finitos conferidos; visão153 inalterada na cadeia. B é XOR exato contra o principal; C é XOR exato contra B. D/E são matrizes BF16 completas contra C. Para usar E, carregue principal->B->C->E, sem aplicar D no caminho de inferência. D é necessário apenas para reproduzir a continuação de treino. Todos os estados/otimizadores/RNG e ativações estão divididos em partes com hashes. Não chame make_native/configure_loops após restaurar.','',
      f'[Manifest selecionado]({manifest}) · [Como usar E](supervised015/attempt_e/REPRODUCE.md) · [Como usar C](supervised015/attempt_c/REPRODUCE.md) · [Resultados completos](supervised015/final_summary.json) · [Diagnóstico EOS](supervised015/eos_mismatch_001.json) · [Método integral](supervised015/METHOD.md).','',
      'Relatórios históricos preservados: [B](supervised015/attempt_b/REPORT.md), [C](supervised015/attempt_c/REPORT.md). A falha inicial do avaliador C foi falta de uma cópia idêntica do JSON; parou antes de gerar qualquer programa e foi retomada sem repetir resultados. O timeout de upload foi investigado por hashes e blobs já recebidos foram recuperados sem recalcular pesos. As provas de publicação remota ficam em supervised015/artifact_verification.json.','',
      '![A/B: apenas diagnósticos de treino](supervised015/attempt_b/training_curve.svg)']
    (ROOT/'SUPERVISED_TEXT_REPORT.md').write_text('\n'.join(lines)+'\n')
    (z/'REPORT.md').write_text('\n'.join(lines).replace('(supervised015/','(../')+'\n')
    for folder in [HERE/'attempt_b',c,d,z]:
        p=folder/'status.json';x=read(p) if p.exists() else {};x.update(status='complete_local_results',model_process_active=False,checkpoint_promoted=False,selected_as_benchmark_specialist=folder.name==selected,process_continues_in_background=False);p.write_text(json.dumps(x,indent=2)+'\n')
    (HERE/'status.json').write_text(json.dumps({'status':'complete_local_results','model_process_active':False,'selected_specialist':selected,'specialist_manifest':manifest,'selected_general_checkpoint':'rsi100/checkpoints/best.pt','checkpoint_promoted':False,'principal_unchanged':True,'publication_verification':'supervised015/artifact_verification.json','process_continues_in_background':False},indent=2)+'\n')
    print(json.dumps({'models':models,'decision':decision,'training':train}))
if __name__=='__main__':main()
